import java.util.Scanner;

public class Main {
    private static int getAngle(String dir) {
        switch (dir) {
            case "norte":
                return 0;
            case "leste":
                return 90;
            case "sul":
                return 180;
            case "oeste":
                return 270;
            default:
                return 0;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (scanner.hasNext()) {
            String a = scanner.next();
            String b = scanner.next();

            int angleA = getAngle(a);
            int angleB = getAngle(b);

            int diff = Math.abs(angleA - angleB);
            int minAngle = Math.min(diff, 360 - diff);

            System.out.println(minAngle);
        }
        scanner.close();
    }
}
